effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord

   /////////////////////////

   const float MATH_PI	= float( 3.14159265359 );

    void Rotate( inout vec2 p, float a ) 
    {
    	p = cos( a ) * p + sin( a ) * vec2( p.y, -p.x );
    }

    float Circle( vec2 p, float r )
    {
        return ( length( p / r ) - 1.0 ) * r;
    }

    float Rand( vec2 c )
    {
    	return fract( sin( dot( c.xy, vec2( 12.9898, 78.233 ) ) ) * 43758.5453 );
    }

    float saturate( float x )
    {
    	return clamp( x, 0.0, 1.0 );
    }

    void BokehLayer( inout vec3 color, vec2 p, vec3 c )   
    {
        float wrap = 450.0;    
        if ( mod( floor( p.y / wrap + 0.5 ), 2.0 ) == 0.0 )
        {
            p.x += wrap * 0.5;
        }    

        vec2 p2 = mod( p + 0.5 * wrap, wrap ) - 0.5 * wrap;
        vec2 cell = floor( p / wrap + 0.5 );
        float cellR = Rand( cell );

        c *= fract( cellR * 3.33 + 3.33 );    
        float radius = mix( 30.0, 70.0, fract( cellR * 7.77 + 7.77 ) );
        p2.x *= mix( 0.9, 1.1, fract( cellR * 11.13 + 11.13 ) );
        p2.y *= mix( 0.9, 1.1, fract( cellR * 17.17 + 17.17 ) );

        float sdf = Circle( p2, radius );
        float circle = 1.0 - smoothstep( 0.0, 1.0, sdf * 0.04 );
        float glow	 = exp( -sdf * 0.025 ) * 0.3 * ( 1.0 - circle );
        color += c * ( circle + glow );
    }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 TanRyu;
        // if (adaptive) { 
        TanRyu = acScreenNorm;
         // }
        // else { 
        // TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        // TanRyu.y*=acLayerSize.y/acLayerSize.x;
        // }

        // TanRyu /= scale;
        TanRyu *= rot2m((0.0+angle)*0.0174533);
        // TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;


        /////////////////////////

    	vec4 fragColor;

    	vec2 uv = TanRyu;
    	vec2 p = ( 2.0 * fragCoord.xy - TanRyu ) / acScreenSize.x * (progressb * 100.0);

        // background
    	vec3 color = mix( vec3( color3.rgb ), vec3( color4.rgb ), dot( uv, vec2( 0.2, 0.7 ) ) );
    	// vec3 color = mix( vec3( 0.3, 0.1, 0.3 ), vec3( 0.1, 0.4, 0.5 ), dot( uv, vec2( 0.2, 0.7 ) ) );

        float time = progressa - 15.0;

        Rotate( p, 0.2 + time * 0.03 );
        BokehLayer( color, p + vec2( -50.0 * time +  0.0, 0.0  ), 3.0 * vec3( color1.rgb ) );
        // BokehLayer( color, p + vec2( -50.0 * time +  0.0, 0.0  ), 3.0 * vec3( 0.4, 0.1, 0.2 ) );
    	Rotate( p, 0.3 - time * 0.05 );
        BokehLayer( color, p + vec2( -70.0 * time + 33.0, -33.0 ), 3.5 * vec3( 0.6, 0.4, 0.2 ) );
    	Rotate( p, 0.5 + time * 0.07 );
        BokehLayer( color, p + vec2( -60.0 * time + 55.0, 55.0 ), 3.0 * vec3( 0.4, 0.3, 0.2 ) );
        Rotate( p, 0.9 - time * 0.03 );
        BokehLayer( color, p + vec2( -25.0 * time + 77.0, 77.0 ), 3.0 * vec3( 0.4, 0.2, 0.1 ) );    
        Rotate( p, 0.0 + time * 0.05 );
        BokehLayer( color, p + vec2( -15.0 * time + 99.0, 99.0 ), 3.0 * vec3( color2.rgb ) );     
        // BokehLayer( color, p + vec2( -15.0 * time + 99.0, 99.0 ), 3.0 * vec3( 0.2, 0.0, 0.4 ) );     

    	fragColor = vec4( color, 1.0 );

    	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            // vec4 gradmap;
            // float luminance = dot(fragColor.rgb, luminanceWeighting);
            // gradmap = mix(color1,color2,luminance)*fragColor.a;
    	    // vec4 factor = mix(texColorX,gradmap,alpha);
    	vec4 factor = mix(texColorX,fragColor,alpha);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = resultfinal;
    }
